#include "sen66_i2c.h"
#include "sensirion_common.h"
#include "sensirion_i2c_hal.h"
#include <inttypes.h>  // PRIx64
#include <stdio.h>     // printf

#define sensirion_hal_sleep_us sensirion_i2c_hal_sleep_usec

int main(void) {
    int16_t error = NO_ERROR;
    sensirion_i2c_hal_init();
    sen66_init(SEN66_I2C_ADDR_6B);

    int32_t humi = 0;
    int16_t t = 0;

    error = sen66_stop_measurement();
    if (error != NO_ERROR) {
        printf("%s\n", "stop measurement not successful");
    }

    sensirion_hal_sleep_us(50000);
    error = sen66_activate_sht_heater();
    if (error != NO_ERROR) {
        printf("%s\n", "stop measurement not successful");
    }

    humi = 0;
    while (true) {
        sensirion_hal_sleep_us(50000);
        error = sen66_get_sht_heater_measurements(&humi, &t);
        if (error != NO_ERROR) {
            printf("%s\n", "stop measurement not successful");
        }

        printf("current temperature: %i\n", t);
        printf("current humidity: %i\n", humi);
        if (humi == 32767) {
            break;
        }
    }
    error = sen66_start_continuous_measurement();
    if (error != NO_ERROR) {
        printf("%s\n", "stop measurement not successful");
    }

    sensirion_hal_sleep_us(1000000);
    uint8_t padding = 0;
    bool data_ready = false;
    uint16_t mass_concentration_pm1p0 = 0;
    uint16_t mass_concentration_pm2p5 = 0;
    uint16_t mass_concentration_pm4p0 = 0;
    uint16_t mass_concentration_pm10p0 = 0;
    int16_t ambient_humidity = 0;
    int16_t ambient_temperature = 0;
    int16_t voc_index = 0;
    int16_t nox_index = 0;
    uint16_t co2 = 0;
    uint16_t repetition = 0;

    for (repetition = 0; repetition < 100; repetition++) {
        error = sen66_get_data_ready(&padding, &data_ready);
        if (error != NO_ERROR) {
            printf("error executing get_data_ready(): %i\n", error);
            continue;
        }
        if (data_ready) {
            //
            // Readout data from the sensor
            error = sen66_read_measured_values_as_integers(
                &mass_concentration_pm1p0, &mass_concentration_pm2p5,
                &mass_concentration_pm4p0, &mass_concentration_pm10p0,
                &ambient_humidity, &ambient_temperature, &voc_index, &nox_index,
                &co2);
            if (error != NO_ERROR) {
                printf(
                    "error executing read_measured_values_as_integers(): %i\n",
                    error);
                continue;
            }
            printf("Mass concentration pm1p0 [µg/m³]: %.2f\n",
                   mass_concentration_pm1p0 / 10.0);
            printf("Mass concentration pm2p5 [µg/m³]: %.2f\n",
                   mass_concentration_pm2p5 / 10.0);
            printf("Mass concentration pm4p0 [µg/m³]: %.2f\n",
                   mass_concentration_pm4p0 / 10.0);
            printf("Mass concentration pm10p0 [µg/m³]: %.2f\n",
                   mass_concentration_pm10p0 / 10.0);
            printf("Ambient humidity [%]: %.2f\n", ambient_humidity / 100.0);
            printf("Ambient temperature [°C]: %.2f\n",
                   ambient_temperature / 200.0);
            printf("VOC index: %i\n", voc_index);
            printf("NOX index: %i\n", nox_index);
            printf("CO₂ [ppm]: %u\n", co2);
        }
    }

    return NO_ERROR;
}
